def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    N, M, K = map(int, data[0].split())
    C = []
    A = []
    R = []

    for i in range(1, M + 1):
        buf = data[i].split()
        C.append(int(buf[0]))
        A.append(list(map(int, buf[1:-1])))
        R.append(buf[-1])

    ans = 0
    for bit in range(1 << N):
        valid = True
        for i in range(M):
            cnt = 0
            for j in range(C[i]):
                if (bit >> (A[i][j] - 1)) & 1:
                    cnt += 1
            if cnt >= K and R[i] == "o":
                continue
            if cnt < K and R[i] == "x":
                continue
            valid = False
            break
        if valid:
            ans += 1

    print(ans)
